using System.Collections.Generic;

/// <summary>
/// Teacher Rachel's pronunciation of every stress-checked word, as
/// PronunciationAssessor compares an answer with it: for the stressed
/// syllable against each neighbour, the three cues (length, loudness, pitch)
/// of her own recording, and of the same recording with the stress moved.
///
/// The numbers live in PronunciationReferenceData.cs, which is GENERATED by
/// PronunciationReferenceBuilder from Assets/Audio/VO/word_*.wav - re-run it
/// (Tools/test_stress_rules.sh generate, or Tools > SALINLAHI > Rebuild
/// Stress References) whenever a word is re-recorded.
///
/// trusted: under every simulated phone (room noise at three levels, the
/// voice as recorded and raised the way a child's is), her own recording is
/// judged Correct and the moved one WrongStress, by the very rule a child's
/// answer meets. A word that is not trusted is still judged, but AnswerJudge
/// asks for a clearer answer instead of passing a borderline one.
/// </summary>
public static partial class PronunciationReferences
{
    public struct Entry
    {
        public bool measured;
        public bool trusted;
        public PronunciationAssessor.Contrast[] contrasts;
        /// <summary>This word's calibrated lines; see PronunciationAssessor.</summary>
        public float acceptFrom, rejectFrom;
    }

    private static Dictionary<string, Entry> table;

    /// <summary>Overrides the table (the builder does this to judge Rachel with a fresh reference).</summary>
    public static void Override(string word, Entry e)
    {
        Load();
        table[word] = e;
    }

    public static Entry For(string word)
    {
        Load();
        Entry e;
        if (!string.IsNullOrEmpty(word) && table.TryGetValue(word.Trim(), out e)) return e;
        return new Entry
        {
            measured = false, trusted = false, contrasts = new PronunciationAssessor.Contrast[0],
            acceptFrom = PronunciationAssessor.AcceptAt, rejectFrom = PronunciationAssessor.RejectAt,
        };
    }

    private static void Load()
    {
        if (table != null) return;
        Dictionary<string, Entry> t = new Dictionary<string, Entry>(System.StringComparer.OrdinalIgnoreCase);
        Dictionary<string, List<PronunciationAssessor.Contrast>> contrasts =
            new Dictionary<string, List<PronunciationAssessor.Contrast>>(System.StringComparer.OrdinalIgnoreCase);
        Dictionary<string, bool> trusted = new Dictionary<string, bool>(System.StringComparer.OrdinalIgnoreCase);
        Dictionary<string, float[]> lines = new Dictionary<string, float[]>(System.StringComparer.OrdinalIgnoreCase);

        foreach (Row row in Rows)
        {
            List<PronunciationAssessor.Contrast> list;
            if (!contrasts.TryGetValue(row.word, out list)) contrasts[row.word] = list = new List<PronunciationAssessor.Contrast>();
            list.Add(new PronunciationAssessor.Contrast
            {
                other = row.other,
                rachel = new PronunciationAssessor.Cues { lengthLn = row.rLen, loudnessDb = row.rLoud, pitchSt = row.rPitch, hasPitch = row.hasPitch },
                moved = new PronunciationAssessor.Cues { lengthLn = row.mLen, loudnessDb = row.mLoud, pitchSt = row.mPitch, hasPitch = row.hasPitch },
            });
            trusted[row.word] = row.trusted;
            lines[row.word] = new[] { row.acceptFrom, row.rejectFrom };
        }
        foreach (KeyValuePair<string, List<PronunciationAssessor.Contrast>> kv in contrasts)
            t[kv.Key] = new Entry
            {
                measured = true, trusted = trusted[kv.Key], contrasts = kv.Value.ToArray(),
                acceptFrom = lines[kv.Key][0], rejectFrom = lines[kv.Key][1],
            };
        table = t;
    }

    private struct Row
    {
        public string word;
        public int other;
        public float rLen, rLoud, rPitch, mLen, mLoud, mPitch;
        public bool hasPitch, trusted;
        public float acceptFrom, rejectFrom;

        public Row(string word, int other, float rLen, float rLoud, float rPitch,
                   float mLen, float mLoud, float mPitch, bool hasPitch, bool trusted,
                   float acceptFrom = PronunciationAssessor.AcceptAt, float rejectFrom = PronunciationAssessor.RejectAt)
        {
            this.acceptFrom = acceptFrom; this.rejectFrom = rejectFrom;
            this.word = word; this.other = other;
            this.rLen = rLen; this.rLoud = rLoud; this.rPitch = rPitch;
            this.mLen = mLen; this.mLoud = mLoud; this.mPitch = mPitch;
            this.hasPitch = hasPitch; this.trusted = trusted;
        }
    }
}
